const MERC_LON_MIN = 1.661440801456166;
const MERC_LAT_MAX = 0.1032819879361274;
const MERC_SCALE = 1250.2762500035751;

/** Proyeksi Mercator yang sama dengan yang dipakai untuk membangkitkan path di atas. */
export function projectPoint(lon: number, lat: number): { x: number; y: number } {
	const mercY = Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI) / 360));
	return {
		x: ((lon * Math.PI) / 180 - MERC_LON_MIN) * MERC_SCALE,
		y: (MERC_LAT_MAX - mercY) * MERC_SCALE,
	};
}

